#pragma warning disable CA1502 // One line per struct: long, but flat.

using System.Reflection;
using System.Runtime.InteropServices;

using Vortice.Vulkan;

namespace Egami.Video.Hardware.Tests;

/// <summary>
/// The Vortice.Vulkan structs the hardware codecs pass to the driver have the sizes and field offsets gcc gives the Vulkan headers
/// on 64-bit targets, and the <c>StdVideo*Flags</c> bit-fields pack from the lowest bit of one 32-bit word, as the C headers
/// declare them (all but <c>StdVideoEncodeH264WeightTableFlags</c>, four <c>uint32_t</c> masks). Vortice.Vulkan before 3.4.0 laid the
/// flag structs out wrong; these tests catch a regression in a later version.
/// </summary>
public sealed unsafe class VulkanLayoutTests
{
