        CheckBits<StdVideoH265SpsFlags>(nameof(StdVideoH265SpsFlags.sps_temporal_id_nesting_flag), nameof(StdVideoH265SpsFlags.separate_colour_plane_flag), nameof(StdVideoH265SpsFlags.conformance_window_flag), nameof(StdVideoH265SpsFlags.sps_sub_layer_ordering_info_present_flag), nameof(StdVideoH265SpsFlags.scaling_list_enabled_flag), nameof(StdVideoH265SpsFlags.sps_scaling_list_data_present_flag), nameof(StdVideoH265SpsFlags.amp_enabled_flag), nameof(StdVideoH265SpsFlags.sample_adaptive_offset_enabled_flag), nameof(StdVideoH265SpsFlags.pcm_enabled_flag), nameof(StdVideoH265SpsFlags.pcm_loop_filter_disabled_flag), nameof(StdVideoH265SpsFlags.long_term_ref_pics_present_flag), nameof(StdVideoH265SpsFlags.sps_temporal_mvp_enabled_flag), nameof(StdVideoH265SpsFlags.strong_intra_smoothing_enabled_flag), nameof(StdVideoH265SpsFlags.vui_parameters_present_flag), nameof(StdVideoH265SpsFlags.sps_extension_present_flag), nameof(StdVideoH265SpsFlags.sps_range_extension_flag), nameof(StdVideoH265SpsFlags.transform_skip_rotation_enabled_flag), nameof(StdVideoH265SpsFlags.transform_skip_context_enabled_flag), nameof(StdVideoH265SpsFlags.implicit_rdpcm_enabled_flag), nameof(StdVideoH265SpsFlags.explicit_rdpcm_enabled_flag), nameof(StdVideoH265SpsFlags.extended_precision_processing_flag), nameof(StdVideoH265SpsFlags.intra_smoothing_disabled_flag), nameof(StdVideoH265SpsFlags.high_precision_offsets_enabled_flag), nameof(StdVideoH265SpsFlags.persistent_rice_adaptation_enabled_flag), nameof(StdVideoH265SpsFlags.cabac_bypass_alignment_enabled_flag), nameof(StdVideoH265SpsFlags.sps_scc_extension_flag), nameof(StdVideoH265SpsFlags.sps_curr_pic_ref_enabled_flag), nameof(StdVideoH265SpsFlags.palette_mode_enabled_flag), nameof(StdVideoH265SpsFlags.sps_palette_predictor_initializers_present_flag), nameof(StdVideoH265SpsFlags.intra_boundary_filtering_disabled_flag));
        CheckBits<StdVideoH265SpsVuiFlags>(nameof(StdVideoH265SpsVuiFlags.aspect_ratio_info_present_flag), nameof(StdVideoH265SpsVuiFlags.overscan_info_present_flag), nameof(StdVideoH265SpsVuiFlags.overscan_appropriate_flag), nameof(StdVideoH265SpsVuiFlags.video_signal_type_present_flag), nameof(StdVideoH265SpsVuiFlags.video_full_range_flag), nameof(StdVideoH265SpsVuiFlags.colour_description_present_flag), nameof(StdVideoH265SpsVuiFlags.chroma_loc_info_present_flag), nameof(StdVideoH265SpsVuiFlags.neutral_chroma_indication_flag), nameof(StdVideoH265SpsVuiFlags.field_seq_flag), nameof(StdVideoH265SpsVuiFlags.frame_field_info_present_flag), nameof(StdVideoH265SpsVuiFlags.default_display_window_flag), nameof(StdVideoH265SpsVuiFlags.vui_timing_info_present_flag), nameof(StdVideoH265SpsVuiFlags.vui_poc_proportional_to_timing_flag), nameof(StdVideoH265SpsVuiFlags.vui_hrd_parameters_present_flag), nameof(StdVideoH265SpsVuiFlags.bitstream_restriction_flag), nameof(StdVideoH265SpsVuiFlags.tiles_fixed_structure_flag), nameof(StdVideoH265SpsVuiFlags.motion_vectors_over_pic_boundaries_flag), nameof(StdVideoH265SpsVuiFlags.restricted_ref_pic_lists_flag));
        CheckBits<StdVideoH265VpsFlags>(nameof(StdVideoH265VpsFlags.vps_temporal_id_nesting_flag), nameof(StdVideoH265VpsFlags.vps_sub_layer_ordering_info_present_flag), nameof(StdVideoH265VpsFlags.vps_timing_info_present_flag), nameof(StdVideoH265VpsFlags.vps_poc_proportional_to_timing_flag));

        // The multi-bit fields after the four one-bit flags.
        StdVideoH265HrdFlags hrd = default;
        hrd.fixed_pic_rate_general_flag = 0xFF;
        Assert.Equal(0xFF0u, *(uint*)&hrd);
        hrd.fixed_pic_rate_within_cvs_flag = 0xFF;
        hrd.low_delay_hrd_flag = 0xFF;
        Assert.Equal(0xFFFFFF0u, *(uint*)&hrd);
    }

    private static void Check<T>(int size, params (string Field, int Offset)[] fields)
        where T : unmanaged
    {
        Assert.True(sizeof(T) == size, $"sizeof({typeof(T).Name}) is {sizeof(T)}; the C headers give {size}.");
        foreach ((string field, int offset) in fields)
        {
            int actual = (int)Marshal.OffsetOf<T>(field);
            Assert.True(actual == offset, $"{typeof(T).Name}.{field} is at {actual}; the C headers put it at {offset}.");
        }
    }

    /// <summary>Sets each of the one-bit <paramref name="flags"/> in turn and checks it lands on the next bit of one 32-bit word.</summary>
    private static void CheckBits<T>(params string[] flags)
        where T : unmanaged
    {
        Assert.Equal(4, sizeof(T));
        for (int bit = 0; bit < flags.Length; bit++)
        {
            object boxed = default(T);
            typeof(T).GetProperty(flags[bit], BindingFlags.Public | BindingFlags.Instance)!.SetValue(boxed, 1u);
            T value = (T)boxed;
            Assert.True(*(uint*)&value == 1u << bit, $"{typeof(T).Name}.{flags[bit]} sets {*(uint*)&value:X8}, not bit {bit}.");
        }
    }
}
